/**
 * PREVIEW-ONLY data for the "vs" comparison template
 * (components/marketing/comparisontemplate/*). Net-new; touches no live page,
 * shared component, or route. Rendered only at /preview/comparison.
 *
 * DIRECTION: Nxeon vs DigitalOcean (managed VPS / cloud hosting) — the format
 * that ranks in Google AND gets cited by AI assistants, so every row is written
 * to be *honest* and *checkable*. Rows are grouped (pricing / specs / support /
 * platform) exactly like the live comparison surface (CompareTable +
 * ComparePageLayout), and the verdict is three-way on purpose:
 *
 *   - "win"   → a genuine Nxeon differentiator (cyan check on the Nxeon side).
 *   - "tie"   → an honest, even match (a neutral dash — no manufactured win).
 *   - "other" → DigitalOcean is the better fit here, and we say so.
 *
 * A comparison that only ever "wins" reads as marketing and gets discounted by
 * readers and by AI assistants alike; crediting the competitor where they lead
 * is exactly what makes the wins believable. Reviews are ILLUSTRATIVE sample
 * content (same status as the live <Testimonials/>) — no fabricated counts, and
 * the real Trustpilot/HostAdvice/Google numbers come from <ReviewBadges/>.
 */

export type Verdict = "win" | "tie" | "other";

export type CompareRow = {
  /** The feature axis, e.g. "Automatic backups". */
  feature: string;
  /** Nxeon's value for this row. */
  nxeon: string;
  /** The competitor's value for this row. */
  other: string;
  /** "win" → Nxeon leads · "tie" → even · "other" → competitor leads. */
  verdict: Verdict;
  /** One-line, honest context shown under the feature. */
  note: string;
};

export type CompareGroup = {
  /** Section label, e.g. "Pricing & terms". */
  label: string;
  rows: CompareRow[];
};

export type SwitchReason = {
  icon: "shield" | "backup" | "support" | "bolt";
  title: string;
  body: string;
};

export type MiniReview = {
  id: string;
  quote: string;
  name: string;
  meta: string;
};

export type Faq = { q: string; a: string };

export const COMPETITOR = {
  name: "DigitalOcean",
  /** Lower-case slug → real logo at /public/logos/<slug>.svg (drop-in convention). */
  slug: "digitalocean",
  /** Neutral one-liner for how DigitalOcean positions itself — used in the header. */
  kind: "unmanaged cloud",
} as const;

/**
 * Honest per-feature rows, grouped like the live comparison table. Order inside
 * each group leads with the strongest, most-cited facts. Every value is a public,
 * checkable claim — no invented competitor figures.
 */
export const COMPARE_GROUPS: CompareGroup[] = [
  {
    label: "Pricing & terms",
    rows: [
      {
        feature: "First month free",
        nxeon: "Included on hosting plans",
        other: "Pay from day one",
        verdict: "win",
        note: "New Nxeon hosting accounts get the first month on the house — try the real thing before you commit a cent.",
      },
      {
        feature: "Automatic backups",
        nxeon: "Included, no surcharge",
