        other: "Hourly, capped monthly + usage add-ons",
        verdict: "tie",
        note: "Different, not better: hourly billing suits bursty, spin-up-spin-down work; a flat all-in price suits always-on projects.",
      },
    ],
  },
  {
    label: "Performance & specs",
    rows: [
      {
        feature: "NVMe SSD storage",
        nxeon: "Enterprise NVMe on a ZFS mirror",
        other: "SSD or NVMe, by Droplet type",
        verdict: "tie",
        note: "Both are genuinely fast. Ours sits on a ZFS mirror for snapshot-friendly backups and data integrity.",
      },
      {
        feature: "Deploy speed",
        nxeon: "~47 seconds to live",
        other: "Under a minute",
        verdict: "tie",
        note: "Both spin up fast — we're not going to pretend a few seconds is a moat, because it isn't.",
      },
      {
        feature: "Dedicated IPv4",
        nxeon: "Included on every plan",
        other: "Included per Droplet",
        verdict: "tie",
        note: "A dedicated IPv4 ships with the box on both sides — table stakes, and we treat it that way.",
      },
      {
        feature: "Global regions",
        nxeon: "Single Singapore node",
        other: "Datacentres across the globe",
        verdict: "other",
        note: "If you need US/EU regions or a worldwide footprint, DigitalOcean wins this outright. We're one low-latency node for Asia-Pacific.",
      },
    ],
  },
  {
    label: "Management & support",
    rows: [
      {
        feature: "Managed & monitored",
        nxeon: "Fully managed, monitored 24/7",
        other: "Unmanaged — you run the OS",
        verdict: "win",
        note: "24/7 here means automated monitoring and auto-restarts, not a night-shift call centre — but you're not the one patching at 2am.",
      },
      {
        feature: "Human support",
        nxeon: "A real person, every plan",
        other: "Docs & community; paid support tiers",
        verdict: "win",
        note: "You reach a human who can actually touch your server — no support-tier paywall to unlock a reply.",
      },
      {
        feature: "Free managed migration",
        nxeon: "We move apps, databases & containers",
        other: "Do-it-yourself",
        verdict: "win",
        note: "A read-only scan finds your stack, then we copy files to the same paths and bring Docker/compose + databases back up. You watch.",
      },
    ],
  },
  {
    label: "Platform & ecosystem",
    rows: [
      {
        feature: "Game servers",
        nxeon: "First-class — Minecraft & more, one-click",
        other: "Possible, but you build it yourself",
        verdict: "win",
        note: "Game servers are a headline use case here, with one-click setup and sane defaults. On a plain Droplet you wire it up yourself.",
      },
      {
        feature: "Domains",
        nxeon: "Register & manage in the same dashboard",
        other: "Not a domain registrar",
        verdict: "win",
        note: "Buy and point a domain without leaving your hosting account. DigitalOcean does DNS, but you register the name elsewhere.",
      },
      {
        feature: "Managed DBs, Kubernetes & LBs",
        nxeon: "Bring your own — full root",
        other: "Large off-the-shelf managed menu",
        verdict: "other",
        note: "Want managed Postgres, Kubernetes or load balancers you don't run yourself? That's DigitalOcean's turf, and a real reason to pick them.",
      },
      {
        feature: "DDoS protection",
        nxeon: "Included",
        other: "Included",
        verdict: "tie",
        note: "Network-level DDoS mitigation ships on both — table stakes, and we treat it that way.",
      },
    ],
  },
];

/** Flat row list, handy for schema/derived counts. */
export const COMPARE_ROWS: CompareRow[] = COMPARE_GROUPS.flatMap((g) => g.rows);

/**
 * Honest three-way scoreboard, derived from the rows so the hero can never drift
 * from the table — and so the competitor's genuine wins are counted, not hidden.
 */
export const SCORE = {
  nxeonWins: COMPARE_ROWS.filter((r) => r.verdict === "win").length,
  ties: COMPARE_ROWS.filter((r) => r.verdict === "tie").length,
  otherWins: COMPARE_ROWS.filter((r) => r.verdict === "other").length,
  total: COMPARE_ROWS.length,
};

export const SWITCH_REASONS: SwitchReason[] = [
  {
    icon: "shield",
    title: "You stop being your own sysadmin",
    body: "Unmanaged droplets are yours to patch, harden and babysit. Nxeon is managed and monitored — restarts and updates just happen, so you ship instead of firefighting.",
  },
  {
