/** Illustrative sample reviews — a generic archetype, never a real named person or metric. */
export const REVIEWS: MiniReview[] = [
  {
    id: "c1",
    quote:
      "Moved three droplets over in an afternoon. The migration did the boring parts — files, databases, compose — and told me the one thing to check by hand.",
    name: "Marc D.",
