"use client";

/**
 * PREVIEW TEMPLATE 1 — Competitor "vs" comparison page (Nxeon vs DigitalOcean).
 *
 * The centrepiece is a credible, grouped head-to-head table (a real <table> for
 * SEO + AI-assistant citation; a stacked card view on mobile) built to the same
 * standard as the live comparison surface (CompareTable + ComparePageLayout):
 * rows grouped by pricing / specs / support / platform, real competitor logos in
 * the column headers, a DB-fed Nxeon "from" price, an HONEST three-way verdict
 * (Nxeon wins · even · DigitalOcean wins) and a trademark/accuracy disclaimer.
 * Around it: an honest animated scoreboard that counts straight from the table
 * (competitor wins included), a "why teams switch" narrative, a free-migration
 * CTA that reuses the live MigrationScreens animation, the real third-party
 * ReviewBadges strip, a straight-answer decision grid and an FAQ.
 *
 * Net-new, preview-only. This is a "use client" component, so the server-only
 * bits it needs — the CompetitorLogo marks and the async ReviewBadges — are
 * rendered by the server page (app/(marketing)/preview/comparison/page.tsx) and
 * passed in as props. Every motion path respects prefers-reduced-motion. Reuses
 * only shared brand primitives (.rail / .card / .btn-deploy / grad-text /
 * eyebrow …) and the `pv-*` keyframes already in globals.css — adds no CSS.
 */

import Link from "next/link";
import { useEffect, useRef, useState, type ReactNode } from "react";
import { MigrationScreens } from "@/components/marketing/showcase/MigrationScreens";
import {
  IconCheck,
  IconBolt,
  IconShield,
  IconBackup,
  IconSupport,
} from "@/components/marketing/icons";
import {
  COMPETITOR,
  COMPARE_GROUPS,
  SCORE,
  SWITCH_REASONS,
  CHOOSE_NXEON,
  CHOOSE_OTHER,
  REVIEWS,
  FAQ,
  DISCLAIMER,
  type CompareRow,
  type CompareGroup,
  type SwitchReason,
  type Verdict,
} from "./data";

export type ComparisonTemplateProps = {
  /** Nxeon mark, pre-rendered on the server (CompetitorLogo slug="nxeon"). */
  nxeonLogo?: ReactNode;
  /** Competitor mark, pre-rendered on the server (CompetitorLogo slug=…). */
  competitorLogo?: ReactNode;
  /** Real third-party review strip (ReviewBadges), rendered on the server. */
  reviewBadges?: ReactNode;
  /** DB-fed Nxeon entry price, e.g. "$6.49/mo" — shown as a header badge. */
  fromLabel?: string;
};

/* ── self-contained motion hooks ─────────────────────────────────────────── */
function usePrefersReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia?.("(prefers-reduced-motion: reduce)");
    if (!mq) return;
    setReduced(mq.matches);
    const on = () => setReduced(mq.matches);
    mq.addEventListener?.("change", on);
    return () => mq.removeEventListener?.("change", on);
  }, []);
  return reduced;
}

function useInViewOnce<T extends HTMLElement = HTMLDivElement>(margin = "0px 0px -12% 0px") {
  const ref = useRef<T | null>(null);
  const [seen, setSeen] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el || typeof IntersectionObserver === "undefined") {
      setSeen(true);
      return;
    }
    const io = new IntersectionObserver(
      ([e]) => {
        if (e.isIntersecting) {
          setSeen(true);
          io.disconnect();
        }
      },
      { threshold: 0.15, rootMargin: margin },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [margin]);
  return { ref, seen };
}

function useCountUp(target: number, active: boolean, duration = 1000, reduced = false) {
  const [val, setVal] = useState(reduced ? target : 0);
  useEffect(() => {
    if (!active) return;
    if (reduced) {
      setVal(target);
      return;
    }
    let raf = 0;
    const start = performance.now();
    const tick = (now: number) => {
      const t = Math.min(1, (now - start) / duration);
      const eased = 1 - Math.pow(1 - t, 3);
      setVal(Math.round(target * eased));
      if (t < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [target, active, duration, reduced]);
  return val;
}

/* ── atoms ───────────────────────────────────────────────────────────────── */
const REASON_ICON: Record<SwitchReason["icon"], (p: { size?: number; className?: string }) => React.ReactElement> = {
  shield: IconShield,
  backup: IconBackup,
  support: IconSupport,
  bolt: IconBolt,
};

/** Text fallback marks, used only if the server didn't pass real logos. */
function NxeonMark({ className = "" }: { className?: string }) {
  return <span className={`font-semibold tracking-tight ${className}`}>Nxeon</span>;
}
function CompetitorMark({ className = "" }: { className?: string }) {
  return <span className={`font-semibold tracking-tight ${className}`}>{COMPETITOR.name}</span>;
}

/* ── verdict markers ─────────────────────────────────────────────────────── */
/** Cyan check — a genuine Nxeon win. */
function WinCheck({ shown = true }: { shown?: boolean }) {
  return (
    <span
      className="inline-flex h-6 w-6 flex-none items-center justify-center rounded-full bg-accent-cyan/15 text-accent-cyan ring-1 ring-accent-cyan/30 transition-all duration-500"
      style={{ transform: shown ? "scale(1)" : "scale(0.4)", opacity: shown ? 1 : 0 }}
      aria-hidden
    >
      <IconCheck size={15} />
    </span>
  );
}

/** Slate check — the other side genuinely leads this row (honest). */
function LeadCheck() {
  return (
    <span
      className="inline-flex h-6 w-6 flex-none items-center justify-center rounded-full bg-white/[0.06] text-slate-300 ring-1 ring-white/10"
      aria-hidden
    >
      <IconCheck size={15} />
    </span>
  );
}

/** Neutral dot — present, but not the differentiator on this row. */
function NeutralDot() {
  return (
    <span
      className="inline-flex h-6 w-6 flex-none items-center justify-center rounded-full bg-white/[0.03] text-slate-500 ring-1 ring-white/10"
      aria-hidden
    >
      <span className="block h-[2px] w-2.5 rounded-full bg-slate-500" />
    </span>
  );
}

function nxeonMarker(v: Verdict, shown: boolean): React.ReactElement {
  if (v === "win") return <WinCheck shown={shown} />;
  return <NeutralDot />;
}
function otherMarker(v: Verdict): React.ReactElement | null {
  if (v === "other") return <LeadCheck />;
  if (v === "tie") return <NeutralDot />;
  return null;
}

/** Small "who leads" pill for the feature cell / mobile card. */
function VerdictPill({ v }: { v: Verdict }) {
  if (v === "win")
    return (
      <span className="inline-flex items-center gap-1 rounded-full bg-accent-cyan/12 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-accent-cyan">
        <IconCheck size={11} /> Nxeon wins
      </span>
    );
  if (v === "other")
    return (
      <span className="inline-flex items-center rounded-full bg-white/[0.06] px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-slate-300">
        {COMPETITOR.name} wins
      </span>
    );
  return (
    <span className="inline-flex items-center rounded-full bg-white/[0.04] px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-slate-500">
      Even
    </span>
  );
}

/* ── honest animated scoreboard (hero visual) ────────────────────────────── */
function ScoreBoard() {
  const reduced = usePrefersReducedMotion();
  const { ref, seen } = useInViewOnce<HTMLDivElement>();
  const wins = useCountUp(SCORE.nxeonWins, seen, 900, reduced);
  const ties = useCountUp(SCORE.ties, seen, 1050, reduced);
  const others = useCountUp(SCORE.otherWins, seen, 1200, reduced);

  return (
    <div ref={ref} className={reduced ? "" : "pv-float-slow"}>
      <div className="relative overflow-hidden rounded-3xl border border-white/10 bg-[#080d18]/85 p-6 shadow-2xl shadow-black/50 backdrop-blur-xl sm:p-7">
        <div
          className="pointer-events-none absolute -inset-16 -z-10 opacity-70"
          style={{ background: "radial-gradient(45% 45% at 82% 0%, rgba(34,211,238,0.20), transparent 70%)" }}
          aria-hidden
        />
        <div className="flex items-center justify-between">
          <span className="inline-flex items-center gap-2 rounded-full bg-emerald-500/12 px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wide text-emerald-300">
            <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
            head-to-head
          </span>
          <span className="font-mono text-[11px] uppercase tracking-widest text-slate-500">
            {SCORE.total} features compared
          </span>
        </div>

        {/* three honest tallies — competitor wins counted, not hidden */}
        <div className="mt-6 grid grid-cols-3 gap-3">
          <div className="rounded-2xl border border-accent-cyan/25 bg-gradient-to-b from-accent-cyan/[0.10] to-transparent px-3 py-5 text-center">
            <p className="font-mono text-3xl font-bold tabular-nums text-accent-cyan sm:text-4xl">{wins}</p>
            <p className="mt-1.5 text-[10px] font-semibold uppercase tracking-wide text-slate-300">Nxeon wins</p>
          </div>
          <div className="rounded-2xl border border-white/[0.07] bg-white/[0.02] px-3 py-5 text-center">
            <p className="font-mono text-3xl font-bold tabular-nums text-slate-300 sm:text-4xl">{ties}</p>
            <p className="mt-1.5 text-[10px] font-semibold uppercase tracking-wide text-slate-500">Even</p>
          </div>
          <div className="rounded-2xl border border-white/[0.07] bg-white/[0.02] px-3 py-5 text-center">
            <p className="font-mono text-3xl font-bold tabular-nums text-slate-300 sm:text-4xl">{others}</p>
            <p className="mt-1.5 text-[10px] font-semibold uppercase tracking-wide text-slate-500">{COMPETITOR.name} wins</p>
          </div>
        </div>

        <div className="mt-4 rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-2.5 text-center text-[12px] leading-relaxed text-slate-400">
          Counted straight from the table below — including the rows where{" "}
          <span className="font-medium text-slate-300">{COMPETITOR.name}</span> honestly wins.
        </div>
      </div>
    </div>
  );
}

/* ── the credible, grouped comparison table ──────────────────────────────── */
function ComparisonTable({
  nxeonLogo,
  competitorLogo,
  fromLabel,
}: {
  nxeonLogo?: ReactNode;
  competitorLogo?: ReactNode;
  fromLabel?: string;
}) {
  const { ref, seen } = useInViewOnce<HTMLDivElement>("0px 0px -8% 0px");

  return (
    <div ref={ref}>
      {/* ── desktop: a real semantic table (SEO + AI citation) ───────────── */}
      <div className="hidden md:block">
        <div className="relative overflow-hidden rounded-3xl border border-white/[0.08] bg-navy-900/60 p-2 backdrop-blur-md">
          {/* violet glow behind the Nxeon column */}
          <div
            className="pointer-events-none absolute inset-y-2 left-[26%] w-[40%] rounded-2xl"
            style={{
              background: "linear-gradient(180deg, rgba(111,71,245,0.10), rgba(34,211,238,0.04) 60%, transparent)",
              boxShadow: "inset 0 0 0 1px rgba(111,71,245,0.22)",
            }}
            aria-hidden
          />
          <table className="relative w-full border-separate border-spacing-0 text-sm">
            <thead>
              <tr>
                <th className="w-[26%] px-5 py-5 text-left align-bottom">
                  <span className="text-[11px] font-semibold uppercase tracking-wider text-slate-500">Compared</span>
                </th>
                <th className="w-[40%] px-5 py-5 text-left align-bottom">
                  <span className="flex items-center gap-2">
                    {nxeonLogo ?? <NxeonMark className="text-xl text-white" />}
                    <span className="rounded-full bg-accent-cyan/12 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-accent-cyan">
                      managed
                    </span>
                  </span>
                  <span className="mt-2 block text-[11px] font-medium text-accent-cyan/80">
                    {fromLabel ? (
                      <>
                        from <span className="font-semibold text-accent-cyan">{fromLabel}</span> · first month free
                      </>
                    ) : (
                      "first month free"
                    )}
                  </span>
                </th>
                <th className="w-[34%] px-5 py-5 text-left align-bottom">
                  <span className="flex items-center">
                    {competitorLogo ?? <CompetitorMark className="text-lg text-slate-300" />}
                  </span>
                  <span className="mt-2 block text-[11px] font-medium text-slate-600">{COMPETITOR.kind}</span>
                </th>
              </tr>
            </thead>
            <tbody>
              {COMPARE_GROUPS.map((group) => (
                <TableGroup key={group.label} group={group} seen={seen} />
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* ── mobile: stacked comparison cards, grouped (no awkward h-scroll) ── */}
