        {/* header marks so the reader knows the two sides */}
        <div className="flex items-center justify-between rounded-2xl border border-white/[0.07] bg-navy-900/60 px-4 py-3 backdrop-blur-md">
          <span className="flex items-center gap-2">
            {nxeonLogo ?? <NxeonMark className="text-base text-white" />}
          </span>
          <span className="font-mono text-[11px] uppercase tracking-widest text-slate-600">vs</span>
          <span className="flex items-center">
            {competitorLogo ?? <CompetitorMark className="text-base text-slate-300" />}
          </span>
        </div>
        {COMPARE_GROUPS.map((group) => (
          <div key={group.label} className="space-y-3">
            <p className="px-1 text-[11px] font-semibold uppercase tracking-[0.14em] text-slate-500">{group.label}</p>
            {group.rows.map((row, i) => (
              <MobileRowCard key={row.feature} row={row} seen={seen} index={i} />
            ))}
          </div>
        ))}
      </div>

      <p className="mt-6 text-center text-[11px] leading-relaxed text-slate-600">{DISCLAIMER}</p>
    </div>
  );
}

function TableGroup({ group, seen }: { group: CompareGroup; seen: boolean }) {
  return (
    <>
      <tr>
        <td colSpan={3} className="px-5 pb-2 pt-6">
          <span className="text-[11px] font-semibold uppercase tracking-[0.14em] text-slate-500">{group.label}</span>
        </td>
      </tr>
      {group.rows.map((row, i) => (
        <TableRow key={row.feature} row={row} seen={seen} index={i} />
      ))}
    </>
  );
}

function TableRow({ row, seen }: { row: CompareRow; seen: boolean; index: number }) {
  const om = otherMarker(row.verdict);
  return (
    <tr className="group">
      {/* feature + honest note + who-leads pill */}
      <td className="border-t border-white/[0.06] px-5 py-4 align-top">
        <span className="block text-[13px] font-semibold text-white">{row.feature}</span>
        <span className="mt-1.5 block"><VerdictPill v={row.verdict} /></span>
        <span className="mt-1.5 block max-w-[24ch] text-[11px] leading-relaxed text-slate-500">{row.note}</span>
      </td>
      {/* Nxeon — emphasised */}
      <td className="border-t border-accent-cyan/15 px-5 py-4 align-top transition-colors group-hover:bg-white/[0.02]">
        <span className="flex items-start gap-2.5">
          {nxeonMarker(row.verdict, seen)}
          <span
            className={`text-[13px] leading-snug ${
              row.verdict === "win" ? "font-medium text-slate-100" : "text-slate-300"
            }`}
          >
            {row.nxeon}
          </span>
        </span>
      </td>
      {/* competitor — neutral, but credited when it leads */}
      <td className="border-t border-white/[0.06] px-5 py-4 align-top">
        <span className="flex items-start gap-2.5">
          {om ?? <span className="h-6 w-6 flex-none" aria-hidden />}
          <span
            className={`text-[13px] leading-snug ${
              row.verdict === "other" ? "font-medium text-slate-200" : "text-slate-400"
            }`}
          >
            {row.other}
          </span>
        </span>
      </td>
    </tr>
  );
}

function MobileRowCard({ row, seen, index }: { row: CompareRow; seen: boolean; index: number }) {
  return (
    <div
      className="rounded-2xl border border-white/[0.07] bg-navy-900/60 p-4 backdrop-blur-md transition-all duration-500"
      style={{
        transitionDelay: `${index * 55}ms`,
        opacity: seen ? 1 : 0,
        transform: seen ? "translateY(0)" : "translateY(10px)",
      }}
    >
      <div className="flex items-center justify-between gap-3">
        <span className="text-[13px] font-semibold text-white">{row.feature}</span>
        <VerdictPill v={row.verdict} />
      </div>
      <p className="mt-1.5 text-[11px] leading-relaxed text-slate-500">{row.note}</p>
      <div className="mt-3 grid grid-cols-2 gap-2">
        <div
          className={`rounded-xl px-3 py-2 ${
            row.verdict === "win"
              ? "border border-accent-cyan/20 bg-accent-cyan/[0.05]"
