          <span className="mt-1 block text-[12px] font-medium text-slate-200">{row.nxeon}</span>
        </div>
        <div
          className={`rounded-xl px-3 py-2 ${
            row.verdict === "other"
              ? "border border-white/15 bg-white/[0.04]"
              : "border border-white/[0.06] bg-white/[0.02]"
