          >
            {row.verdict === "other" ? <IconCheck size={12} /> : null} {COMPETITOR.name}
          </span>
          <span className="mt-1 block text-[12px] text-slate-400">{row.other}</span>
        </div>
      </div>
    </div>
  );
}

